layer.css:
@import url("https://fonts.googleapis.com/css2?family=Inter:wght@400;500;700;900&family=JetBrains+Mono:wght@400;600&display=swap");
[data-ryt="footer"] { color: var(--ryt-text); border-top: 1px solid rgb(229, 229, 229); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-body); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-body); font-size: 14.4px; font-weight: 600; font-style: normal; line-height: 1.5; letter-spacing: 0.288px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: color 0.15s, text-decoration 0.15s }
[data-ryt="header"] { border-bottom: 1px solid color-mix(in srgb, var(--ryt-text) 40%, transparent); border-top: none }
[data-ryt="nav"] a:hover { color: #111213; text-decoration-line: underline; text-decoration-style: initial; text-decoration-color: initial; text-underline-offset: 3px; text-decoration-thickness: 1px }
